-- Signed balances must be conserved across merge and replay, including refund debt.
insert into auth.users(id,email,aud,role,is_anonymous,created_at) values ('a4000001-0000-4000-8000-000000000001',null,'authenticated','authenticated',true,now()),('b4000001-0000-4000-8000-000000000001','debt-1@example.invalid','authenticated','authenticated',false,now());
