update public.profiles set credits=-80,promotional_credits=-10 where id='b4000001-0000-4000-8000-000000000001';
select is(public.merge_guest_account('a4000001-0000-4000-8000-000000000001','b4000001-0000-4000-8000-000000000001','mobile')->>'status','merged','case 1: signed merge succeeds');
select is((select credits from public.profiles where id='b4000001-0000-4000-8000-000000000001'),-80,'case 1: total credits including debt are conserved');
