select is((select credits_moved from public.account_merges where guest_user_id='a4000001-0000-4000-8000-000000000001'),0,'case 1: ledger records signed transfer');
select is(public.merge_guest_account('a4000001-0000-4000-8000-000000000001','b4000001-0000-4000-8000-000000000001','mobile')->>'status','already_merged','case 1: replay is idempotent');
select is((select credits from public.profiles where id='b4000001-0000-4000-8000-000000000001'),-80,'case 1: replay preserves debt');
